          "text": "这园子仿佛是乱山中凭空擎出的一只金漆托盘。墙里的春天，不过是虚应个景儿，谁知星星之火，可以燎原，墙里的春延烧到墙外去，满山轰轰烈烈开着野杜鹃。",
