          "id": "qing-first-fog-1",
          "text": "那是个潮湿的春天的晚上，香港山上的雾是最有名的。梁家那白房子黏黏地融化在白雾里，只看见绿玻璃窗里晃动着灯光，绿幽幽地，一方一方，像薄荷酒里的冰块。",
          "kind": "atmosphere",
