      "sceneTitle": "蛀空了的世界",
      "sceneIntro": "婚礼后的创伤仍未被说破，罗杰在海边感到一种麻木而持续的疼痛。",
      "narrativeOrder": 3,
      "excerpts": [
        {
          "id": "qing-second-beach-1",
          "text": "整个的世界像一个蛀空了的牙齿，麻木木的，倒也不觉得什么，只是风来的时候，隐隐的有一点酸痛。",
          "kind": "reflection",
          "language": "zh"
        }
      ],
