      "sceneTitle": "没有月亮的月色",
      "sceneIntro": "修道院会客室里，霓喜面对新的生活提议，窗边绣球花替未出现的月亮照亮她的迟疑。",
      "narrativeOrder": 4,
      "excerpts": [
        {
          "id": "qing-loop-convent-1",
          "text": "靠墙地上搁着一盆绣球花，那绣球花白里透蓝，透紫，便在白昼也带三分月色；此时屋子里并没有月亮，似乎就有个月亮照着。",
          "kind": "atmosphere",
          "language": "zh"
        }
      ],
      "placeId": "qing-loop-convent",
